#include "codegen.h"
#include "diagnostics.h"
#include <sstream>
#include <stdexcept>

// ---------------------------------------------------------------------------
// Construction
// ---------------------------------------------------------------------------
CodeGen::CodeGen(int indent_width) : indentWidth_(indent_width) {}

// ---------------------------------------------------------------------------
// Emit helpers
// ---------------------------------------------------------------------------
void CodeGen::emit(const std::string& s)     { out_ += s; }
void CodeGen::emitLine(const std::string& s) { out_ += s + "\n"; }
void CodeGen::indent()  { ++indentLevel_; }
void CodeGen::dedent()  { if (indentLevel_ > 0) --indentLevel_; }

std::string CodeGen::indentStr() const {
    return std::string(indentLevel_ * indentWidth_, ' ');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------
std::string CodeGen::generate(const Node& program) {
    out_.clear();
    indentLevel_ = 0;
    genProgram(program);
    return out_;
}

// ---------------------------------------------------------------------------
// String escaping
// ---------------------------------------------------------------------------
std::string CodeGen::escapeString(const std::string& s) {
    std::string out;
    for (char c : s) {
        switch (c) {
            case '"':  out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n";  break;
            case '\r': out += "\\r";  break;
            case '\t': out += "\\t";  break;
            default:   out += c;
        }
    }
    return out;
}

// Trim leading/trailing whitespace, collapse internal runs to a single space.
std::string CodeGen::escapeJSXText(const std::string& raw) {
    std::string s;
    bool        prevSpace = true;
    for (char c : raw) {
        if (std::isspace((unsigned char)c)) {
            if (!prevSpace) { s += ' '; prevSpace = true; }
        } else {
            s += c;
            prevSpace = false;
        }
    }
    if (!s.empty() && s.back() == ' ') s.pop_back();
    return s;
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------
void CodeGen::genNode(const Node& n) {
    switch (n.kind) {
        // statements
        case NodeKind::Program:          genProgram(n);          break;
        case NodeKind::ImportDecl:       genImportDecl(n);       break;
        case NodeKind::ExportDefaultDecl:genExportDefaultDecl(n);break;
        case NodeKind::ExportNamedDecl:  genExportNamedDecl(n);  break;
        case NodeKind::FunctionDecl:     genFunctionDecl(n);     break;
        case NodeKind::BlockStmt:        genBlockStmt(n);        break;
        case NodeKind::ReturnStmt:       genReturnStmt(n);       break;
        case NodeKind::IfStmt:           genIfStmt(n);           break;
        case NodeKind::ForStmt:          genForStmt(n);          break;
        case NodeKind::WhileStmt:        genWhileStmt(n);        break;
        case NodeKind::VarDecl:          genVarDecl(n);          break;
        case NodeKind::ExprStmt:         genExprStmt(n);         break;
        // expressions
        default:                         genExpr(n);             break;
    }
}

void CodeGen::genProgram(const Node& n) {
    for (const auto& stmt : n.body) {
        emit(indentStr());
        genNode(*stmt);
        emitLine();
    }
}

// ---------------------------------------------------------------------------
// Statements
// ---------------------------------------------------------------------------
void CodeGen::genImportDecl(const Node& n) {
    emit("import ");
    if (n.specifiers.empty()) {
        // import "side-effect"
    } else if (n.specifiers.size() == 1 && n.specifiers[0]->name == "*") {
        emit("* as " + n.specifiers[0]->value);
    } else {
        bool first = true;
        bool hasDefault = false;
        // First check for default (no alias, no '{')
        // Simple approach: emit as-is
        emit("{ ");
        for (const auto& s : n.specifiers) {
            if (!first) emit(", ");
            first = false;
            emit(s->name);
            if (!s->value.empty()) emit(" as " + s->value);
        }
        emit(" }");
    }
    if (!n.source.empty()) emit(" from \"" + n.source + "\"");
    emit(";");
}

void CodeGen::genExportDefaultDecl(const Node& n) {
    emit("export default ");
    genNode(*n.declaration);
}

void CodeGen::genExportNamedDecl(const Node& n) {
    emit("export ");
    genNode(*n.declaration);
}

void CodeGen::genFunctionDecl(const Node& n) {
    if (n.async_) emit("async ");
    emit("function");
    if (!n.name.empty()) emit(" " + n.name);
    emit("(");
    for (size_t i = 0; i < n.params.size(); ++i) {
        if (i) emit(", ");
        emit(n.params[i]->name);
    }
    emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genBlockStmt(const Node& n) {
    emitLine("{");
    indent();
    for (const auto& stmt : n.body) {
        emit(indentStr());
        genNode(*stmt);
        emitLine();
    }
    dedent();
    emit(indentStr() + "}");
}

void CodeGen::genReturnStmt(const Node& n) {
    emit("return");
    if (n.expression) { emit(" "); genExpr(*n.expression); }
    emit(";");
}

void CodeGen::genIfStmt(const Node& n) {
    emit("if ("); genExpr(*n.test); emit(") ");
    genNode(*n.consequent);
    if (n.alternate) { emit(" else "); genNode(*n.alternate); }
}

void CodeGen::genForStmt(const Node& n) {
    emit("for (");
    if (n.init)   genNode(*n.init);  else emit(";");
    emit(" ");
    if (n.test)   genExpr(*n.test);
    emit("; ");
    if (n.update) genExpr(*n.update);
    emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genWhileStmt(const Node& n) {
    emit("while ("); genExpr(*n.test); emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genVarDecl(const Node& n) {
    emit(n.varKind + " ");
    for (size_t i = 0; i < n.declarations.size(); ++i) {
        if (i) emit(", ");
        const Node& d = *n.declarations[i];
        emit(d.name);
        if (d.init) { emit(" = "); genExpr(*d.init); }
    }
    emit(";");
}

void CodeGen::genExprStmt(const Node& n) {
    genExpr(*n.expression);
    emit(";");
}

// ---------------------------------------------------------------------------
// Expressions
// ---------------------------------------------------------------------------
void CodeGen::genExpr(const Node& n) {
    switch (n.kind) {
        case NodeKind::Identifier:          genIdentifier(n);       break;
        case NodeKind::NumericLiteral:      genNumericLiteral(n);   break;
        case NodeKind::StringLiteral:       genStringLiteral(n);    break;
        case NodeKind::TemplateLiteral:     genTemplateLiteral(n);  break;
        case NodeKind::BoolLiteral:         genBoolLiteral(n);      break;
        case NodeKind::NullLiteral:         emit("null");            break;
        case NodeKind::BinaryExpr:          genBinaryExpr(n);       break;
        case NodeKind::UnaryExpr:           genUnaryExpr(n);        break;
        case NodeKind::LogicalExpr:         genLogicalExpr(n);      break;
        case NodeKind::AssignExpr:          genAssignExpr(n);       break;
        case NodeKind::CallExpr:            genCallExpr(n);         break;
        case NodeKind::MemberExpr:          genMemberExpr(n);       break;
        case NodeKind::NewExpr:             genNewExpr(n);          break;
        case NodeKind::ConditionalExpr:     genConditionalExpr(n);  break;
        case NodeKind::SpreadElement:       genSpreadElement(n);    break;
        case NodeKind::ArrayExpr:           genArrayExpr(n);        break;
        case NodeKind::ObjectExpr:          genObjectExpr(n);       break;
        case NodeKind::ArrowFunctionExpr:   genArrowFunctionExpr(n);break;
        case NodeKind::SequenceExpr:        genSequenceExpr(n);     break;
        case NodeKind::JSXElement:          genJSXElement(n);       break;
        case NodeKind::JSXFragment:         genJSXFragment(n);      break;
        // Statements that can appear as expressions (function exprs etc.)
        case NodeKind::FunctionDecl:        genFunctionDecl(n);     break;
        default:
            throw CodeGenError("Unhandled expression node kind " +
                               std::to_string(static_cast<int>(n.kind)));
    }
}

void CodeGen::genIdentifier(const Node& n)     { emit(n.name); }
void CodeGen::genNumericLiteral(const Node& n) { emit(n.value); }
void CodeGen::genStringLiteral(const Node& n)  { emit("\"" + escapeString(n.value) + "\""); }
void CodeGen::genBoolLiteral(const Node& n)    { emit(n.boolVal ? "true" : "false"); }

void CodeGen::genTemplateLiteral(const Node& n) {
    // The lexer stored the raw content (between backticks) in n.value.
    emit("`" + n.value + "`");
}

void CodeGen::genBinaryExpr(const Node& n) {
    emit("("); genExpr(*n.object); emit(" " + n.name + " "); genExpr(*n.property); emit(")");
}

void CodeGen::genUnaryExpr(const Node& n) {
    std::string op = n.name;
    bool isPost = op.size() > 4 && op.substr(op.size() - 4) == "post";
    bool isPre  = op.size() > 3 && op.substr(op.size() - 3) == "pre";
    if (isPre) {
        emit(op.substr(0, op.size() - 3));
        genExpr(*n.object);
    } else if (isPost) {
        genExpr(*n.object);
        emit(op.substr(0, op.size() - 4));
    } else {
        emit(op + " ");
        genExpr(*n.object);
    }
}

void CodeGen::genLogicalExpr(const Node& n)  { genBinaryExpr(n); }
void CodeGen::genAssignExpr(const Node& n)   {
    genExpr(*n.object); emit(" " + n.name + " "); genExpr(*n.property);
}

void CodeGen::genCallExpr(const Node& n) {
    genExpr(*n.callee);
    emit("(");
    for (size_t i = 0; i < n.arguments.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.arguments[i]);
    }
    emit(")");
}

void CodeGen::genMemberExpr(const Node& n) {
    genExpr(*n.object);
    if (n.computed) { emit("["); genExpr(*n.property); emit("]"); }
    else             { emit("."); genExpr(*n.property); }
}

void CodeGen::genNewExpr(const Node& n) {
    emit("new ");
    genExpr(*n.callee);
    emit("(");
    for (size_t i = 0; i < n.arguments.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.arguments[i]);
    }
    emit(")");
}

void CodeGen::genConditionalExpr(const Node& n) {
    emit("(");
    genExpr(*n.test); emit(" ? "); genExpr(*n.consequent); emit(" : "); genExpr(*n.alternate);
    emit(")");
}

void CodeGen::genSpreadElement(const Node& n) { emit("..."); genExpr(*n.object); }

void CodeGen::genArrayExpr(const Node& n) {
    emit("[");
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.children[i]);
    }
    emit("]");
}

void CodeGen::genObjectExpr(const Node& n) {
    emit("{ ");
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        const Node& prop = *n.children[i];
        if (prop.name == "...") { emit("..."); genExpr(*prop.init); }
        else {
            emit(prop.name + ": ");
            genExpr(*prop.init);
        }
    }
    emit(" }");
}

void CodeGen::genArrowFunctionExpr(const Node& n) {
    if (n.async_) emit("async ");
    emit("(");
    for (size_t i = 0; i < n.params.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.params[i]);
    }
    emit(") => ");
    if (!n.body.empty()) {
        if (n.body[0]->kind == NodeKind::BlockStmt)
            genBlockStmt(*n.body[0]);
        else
            genExpr(*n.body[0]);
    }
}

void CodeGen::genSequenceExpr(const Node& n) {
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.children[i]);
    }
}

// ---------------------------------------------------------------------------
// JSX lowering
// ---------------------------------------------------------------------------

// Emit the second argument to React.createElement: props object or null.
void CodeGen::emitJSXProps(const Node& openingEl) {
    if (openingEl.attributes.empty()) {
        emit("null");
        return;
    }
    emit("{ ");
    bool first = true;
    for (const auto& attrPtr : openingEl.attributes) {
        const Node& attr = *attrPtr;
        if (!first) emit(", ");
        first = false;

        if (attr.kind == NodeKind::JSXSpreadAttribute) {
            emit("...");
            genExpr(*attr.expression);
        } else {
            emit(attr.name + ": ");
            if (attr.init) {
                if (attr.init->kind == NodeKind::JSXExpressionContainer)
                    genExpr(*attr.init->expression);
                else
                    genExpr(*attr.init);
            } else {
                emit("true");
            }
        }
    }
    emit(" }");
}

void CodeGen::genJSXElement(const Node& n) {
    const Node& opening = *n.openingElement;
    emit("React.createElement(");

    // First arg: tag name (string for lowercase, identifier for uppercase/member)
    char firstChar = opening.name.empty() ? '\0' : opening.name[0];
    if (std::islower((unsigned char)firstChar)) {
        emit("\"" + opening.name + "\"");
    } else {
        emit(opening.name);
    }

    emit(", ");
    emitJSXProps(opening);

    // Children
    for (const auto& child : n.children) {
        emit(", ");
        genJSXChild(*child);
    }

    emit(")");
}

void CodeGen::genJSXFragment(const Node& n) {
    emit("React.createElement(React.Fragment, null");
    for (const auto& child : n.children) {
        emit(", ");
        genJSXChild(*child);
    }
    emit(")");
}

void CodeGen::genJSXChild(const Node& n) {
    if (n.kind == NodeKind::JSXText) {
        std::string text = escapeJSXText(n.value);
        if (!text.empty()) emit("\"" + escapeString(text) + "\"");
    } else if (n.kind == NodeKind::JSXExpressionContainer) {
        genExpr(*n.expression);
    } else if (n.kind == NodeKind::JSXElement) {
        genJSXElement(n);
    } else if (n.kind == NodeKind::JSXFragment) {
        genJSXFragment(n);
    } else {
        genExpr(n);
    }
}

#include "lexer.h"
#include "parser.h"
#include "codegen.h"
#include "diagnostics.h"

#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

static void printUsage(const char* argv0) {
    std::cerr << "Usage: " << argv0 << " [options] <input.jsx>\n"
              << "Options:\n"
              << "  -o <file>    Write output to file (default: stdout)\n"
              << "  -h           Show this help\n";
}

static std::string readFile(const std::string& path) {
    std::ifstream f(path);
    if (!f) {
        std::cerr << "error: cannot open '" << path << "'\n";
        std::exit(1);
    }
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

int main(int argc, char** argv) {
    std::string inputPath;
    std::string outputPath;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "-h" || arg == "--help") {
            printUsage(argv[0]);
            return 0;
        } else if (arg == "-o") {
            if (++i >= argc) { std::cerr << "error: -o requires a filename\n"; return 1; }
            outputPath = argv[i];
        } else if (arg[0] == '-') {
            std::cerr << "error: unknown option '" << arg << "'\n";
            printUsage(argv[0]);
            return 1;
        } else {
            if (!inputPath.empty()) {
                std::cerr << "error: multiple input files not supported\n";
                return 1;
            }
            inputPath = arg;
        }
    }

    if (inputPath.empty()) {
        printUsage(argv[0]);
        return 1;
    }

    std::string source = readFile(inputPath);

    try {
        Lexer lexer(source);
        auto tokens = lexer.tokenize();

        Parser parser(std::move(tokens));
        auto ast = parser.parse();

        CodeGen gen;
        std::string output = gen.generate(*ast);

        if (outputPath.empty()) {
            std::cout << output;
        } else {
            std::ofstream out(outputPath);
            if (!out) {
                std::cerr << "error: cannot write to '" << outputPath << "'\n";
                return 1;
            }
            out << output;
        }

    } catch (const LexError& e) {
        std::cerr << formatDiag("lex error", e.what(), e.line, e.col) << "\n";
        return 1;
    } catch (const ParseError& e) {
        std::cerr << formatDiag("parse error", e.what(), e.line, e.col) << "\n";
        return 1;
    } catch (const CodeGenError& e) {
        std::cerr << "codegen error: " << e.what() << "\n";
        return 1;
    } catch (const std::exception& e) {
        std::cerr << "error: " << e.what() << "\n";
        return 1;
    }

    return 0;
}

