// Trim leading/trailing whitespace, collapse internal runs to a single space.
std::string CodeGen::escapeJSXText(const std::string& raw) {
    std::string s;
    bool        prevSpace = true;
    for (char c : raw) {
        if (std::isspace((unsigned char)c)) {
            if (!prevSpace) { s += ' '; prevSpace = true; }
        } else {
            s += c;
            prevSpace = false;
        }
    }
    if (!s.empty() && s.back() == ' ') s.pop_back();

