void CodeGen::genExportNamedDecl(const Node& n) {
    emit("export ");
    if (!n.specifiers.empty()) {
        // export { a, b as c } [from "mod"]
        emit("{ ");
        for (size_t i = 0; i < n.specifiers.size(); ++i) {
            if (i) emit(", ");
            emit(n.specifiers[i]->name);
            if (!n.specifiers[i]->value.empty())
                emit(" as " + n.specifiers[i]->value);
        }
        emit(" }");
        if (!n.source.empty()) emit(" from \"" + n.source + "\"");
        emit(";");
    } else if (n.declaration) {
        genNode(*n.declaration);
    }
}

